import{_ as t,C as n,o as d,c,a3 as o,E as i}from"./chunks/framework.BYcGlnQ4.js";const f=JSON.parse('{"title":"Demo","description":"Everything below runs in your browser. The controls are the options randName, randNickname, randWord, randSentence, randLocation, randAge, randGender,…","frontmatter":{},"headers":[],"relativePath":"demo.md","filePath":"en/demo.md","lastUpdated":1791426934000}'),r={name:"demo.md"};function s(h,e,l,u,g,m){const a=n("Demo",!0);return d(),c("div",null,[e[0]||(e[0]=o('<h1 id="demo" tabindex="-1">Demo <a class="header-anchor" href="#demo" aria-label="Permalink to &quot;Demo&quot;">​</a></h1><p>Everything below runs in your browser. The controls are the options <code>randName</code>, <code>randNickname</code>, <code>randWord</code>, <code>randSentence</code>, <code>randLocation</code>, <code>randAge</code>, <code>randGender</code>, <code>randOrganization</code>, <code>randDate</code> and <code>randPhone</code> actually take, the code block under the output is the call your settings amount to, and what you see is drawn fresh every time you press Generate.</p>',2)),i(a),e[1]||(e[1]=o('<h2 id="what-to-try" tabindex="-1">What to try <a class="header-anchor" href="#what-to-try" aria-label="Permalink to &quot;What to try&quot;">​</a></h2><ul><li>Set <code>language</code> to <code>en</code> and <code>realism</code> to <code>invented</code>. The names still read as English and stop being names anybody has — the generator builds them out of syllable templates instead of drawing from the pool.</li><li>Leave <code>language</code> on <code>all</code> and press Generate a few times. Nine scripts, and each name&#39;s length range is resolved for its own language rather than for the batch.</li><li>Pick <code>ru</code> and switch <code>gender</code>. Russian is the one language where the choice is visible from the outside: the patronymic and the surname both inflect.</li><li>On the nickname tab, set <code>theme</code> to <code>animal</code> and <code>wordSeparator</code> to <code>-</code>. The separator counts toward the length range, so a narrow range drops the modifier rather than truncating a word.</li><li>Set <code>maxLength</code> to <code>8</code> on an English nickname. The three-word shapes drop out rather than being truncated — length picks the shape, not the words.</li><li>Turn on <code>randSuffix</code>. The token is attached after the nickname is finished, which is why the length options never have to account for it.</li><li>On the words tab, pick a <code>theme</code> and press Generate. These are the pools a nickname is built from, handed over with nothing added — <code>randAnimal</code> and its twenty-eight siblings are this call with the theme already chosen.</li><li>Switch the decorator to <code>randModifier</code> on the words tab. A modifier in front of a noun is most of what <code>randNickname</code> does, and the code block shows the two functions doing it in the open.</li><li>On the sentence tab, set <code>language</code> to <code>de</code> and then to <code>ru</code>, and turn on the details. Neither language offers an <code>object</code> or a <code>place</code>: both would put the noun in a case its own ending has to change for, so those shapes are not among the ones they declare.</li><li>Type two words into <code>include</code> — <code>brave lion</code> in English, <code>사자 조용히</code> in Korean. Both land in every sentence, and <code>brave</code> becomes a modifier or a predicate depending on what the rest of the shape has room for.</li><li>Set <code>shape</code> to <code>simple</code> and then to <code>complex</code>. The sentence gains a phrase rather than a longer word, which is the same thing <code>minLength</code> does one character at a time.</li><li>On the locations tab, turn on the details and press Generate a few times. Every district sits inside the city beside it and every city inside its region, because each is one the country publishes rather than a name put together.</li><li>Leave <code>randLocation</code> picked, set <code>language</code> to <code>ko</code> and turn off <code>includeCountry</code>. The country stops opening every line, and <code>startsWith</code> on <code>서</code> now draws from 서울특별시 rather than matching nothing.</li><li>Pick <code>randDistrict</code> and set <code>language</code> to <code>en</code>. Nothing comes back: a US location stops at the city, and only Korean has a level below it. Leave <code>language</code> on <code>all</code> and the same call draws Korean alone.</li><li>Pick <code>randRegion</code>, set <code>language</code> to <code>ko</code>, <code>count</code> to <code>20</code> and turn on <code>unique</code>. Sixteen come back, which is every 시·도 there is.</li><li>Pick <code>randCountry</code> and set <code>language</code> to <code>ja</code>, then turn on the details. Every country and territory ISO 3166-1 codes has a name in all nine languages, so this is the one location function that is not held to Korean and English.</li><li>Pick <code>randCity</code> with <code>language</code> on <code>ko</code> and <code>startsWith</code> on <code>수</code>. A 구 that is one of a city&#39;s districts is written with its city, <code>수원시 장안구</code>, the way an address writes it.</li><li>On the ages tab, press Generate a few times, then set <code>distribution</code> to <code>uniform</code>. The first draws mostly people from their twenties to their fifties; the second is as likely to hand back a ninety-year-old as a nine-year-old.</li><li>Set <code>group</code> to <code>senior</code> and <code>maxAge</code> to <code>40</code>. No age is both, so the range wins and the ages come from 0 to 40 rather than nothing at all.</li><li>On the genders tab, turn on <code>includeUnknown</code> and <code>includeNonbinary</code> and set <code>count</code> to <code>50</code>. Unknown comes up four or five times; non-binary once or not at all, since it is about one draw in a hundred.</li><li>Set <code>language</code> to <code>de</code> with <code>includeNonbinary</code> on. German writes <code>Divers</code>, the third option its own forms carry.</li><li>On the organizations tab, set <code>type</code> to <code>company</code> and switch <code>language</code> between <code>es</code> and <code>de</code>. Spanish puts the business in front of the name and German behind it: the order is the language&#39;s template, not the generator&#39;s.</li><li>Leave <code>type</code> on <code>all</code> and pick an <code>industry</code>. Only companies come back, because an industry is a company&#39;s.</li><li>Set <code>language</code> to <code>ko</code> and <code>minLength</code> to <code>12</code>. A Korean organization is usually shorter, so the long kinds are chosen, a company with its legal form or a 종합사회복지관, rather than a short name stretched.</li><li>Turn on the details, set <code>language</code> to <code>ko</code> and <code>startsWith</code> to <code>해</code>. The name starts with it even where <code>주식회사</code> is written in front.</li><li>On the dates tab, set <code>minDate</code> and <code>maxDate</code> both to <code>2024-02</code>. Every date lands in February 2024 and its last day is the 29th, because a string bound names the whole month rather than its first millisecond.</li><li>Set <code>unit</code> to <code>month</code>, <code>count</code> to <code>20</code> and turn on <code>unique</code>. Twelve come back, however often you press Generate, since a year has no more.</li><li>Type <code>YYYY년 M월 D일 A h:mm</code> into <code>format</code>, then <code>[Day] D</code> and <code>Day D</code>. Text outside brackets is read for tokens, so the last one comes out as something like <code>5amy 5</code>: both <code>D</code> and <code>a</code> are tokens.</li><li>On the phone tab, switch <code>country</code> between <code>KR</code>, <code>US</code> and <code>RU</code>. Each writes its numbers its own way: dashes, a bracketed area code, the trunk <code>8</code> in front.</li><li>Turn on <code>includeCountryCode</code> and set <code>separator</code> to <code>&#39;&#39;</code>. That is E.164, the form an SMS gateway expects — and the detail carries it whatever the other options say. A number like this can by chance be real, so it is for a form under test, not for sending anything to.</li><li>Turn on <code>fictional</code> with <code>country</code> on <code>all</code>. Only US and German numbers come back, <code>555-01xx</code> and the Bundesnetzagentur&#39;s drama numbers, because those are the two countries that set numbers aside for films and books; pick <code>KR</code> and nothing comes back at all, rather than a real number.</li><li>Back on the dates tab, type <code>dddd, D MMMM YYYY</code> into <code>format</code> and switch <code>language</code> to <code>de</code>, <code>ru</code> and <code>ko</code>. The names change and the digits stay; Russian writes its month in the genitive, the way a date needs it.</li><li>Set <code>utcOffset</code> to <code>+09:00</code> and leave <code>format</code> empty. The dates end on <code>+09:00</code> rather than <code>Z</code>, and setting <code>minDate</code> and <code>maxDate</code> to the same day keeps every date on that day in Seoul.</li></ul><h2 id="what-this-page-is-not" tabindex="-1">The scope of this page <a class="header-anchor" href="#what-this-page-is-not" aria-label="Permalink to &quot;The scope of this page {#what-this-page-is-not}&quot;">​</a></h2><p>This page is a demonstration rather than a generator to call from a browser at scale. The library itself has no network calls and no dependencies, so the same code runs on a server, in a build script or in a test fixture exactly as it runs here.</p><p>The page draws <strong>without a seed</strong>, so pressing Generate twice gives two different batches. Your own calls do not have to: every generator takes a <code>random</code>, and a seeded one hands back the same batch on every run. <a href="./guide/getting-started#choosing-the-source">Choosing the source</a> shows how.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./guide/getting-started">Getting started</a> — installing it, for whichever of the three packages you use.</li><li><a href="./name/rand-name"><code>randName</code></a>, <a href="./nickname/rand-nickname"><code>randNickname</code></a>, <a href="./word/rand-word"><code>randWord</code></a>, <a href="./sentence/rand-sentence"><code>randSentence</code></a>, <a href="./location/rand-location"><code>randLocation</code></a>, <a href="./age/rand-age"><code>randAge</code></a>, <a href="./gender/rand-gender"><code>randGender</code></a>, <a href="./organization/rand-organization"><code>randOrganization</code></a>, <a href="./date/rand-date"><code>randDate</code></a> and <a href="./phone/rand-phone"><code>randPhone</code></a> — every option in the panel above, written out.</li><li><a href="./guide/languages">Supported languages</a> — what each language can and cannot do.</li></ul>',7))])}const w=t(r,[["render",s]]);export{f as __pageData,w as default};
